
.npc-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--card-pad);
  box-shadow: var(--glow-card);
  transition:
    background var(--transition-smooth),
    border-color var(--transition-smooth),
    box-shadow var(--transition-smooth);
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0.45em;
  min-width: 0;
  width: 100%;
  font-size: 1em;

  &:hover {
    background: var(--bg-card-hover);
    border-color: var(--border-glow);
    box-shadow: var(--glow-accent);
  }

  &--empty {
    opacity: 0.78;
  }
}

/* 顶栏：可点击折叠；名字靠左，社会身份靠右 */
.npc-card-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35em 0.5em;
  position: relative;
  z-index: 1;
  width: 100%;
  margin: 0;
  padding: 0.15em 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: background var(--transition-smooth);

  &:hover:not(:disabled) {
    background: color-mix(in srgb, var(--bg-step) 55%, transparent);
  }

  &:focus-visible {
    outline: 2px solid var(--border-glow);
    outline-offset: 2px;
  }

  &--static,
  &:disabled {
    cursor: default;
  }
}

.npc-card-caret {
  margin-left: auto;
  flex-shrink: 0;
  font-size: 0.85em;
  color: var(--text-muted);
  line-height: 1;
  transition: transform 0.2s ease;
  transform: rotate(0deg);

  &--open {
    transform: rotate(180deg);
  }
}

.npc-card-body {
  display: flex;
  flex-direction: column;
  gap: 0.45em;
  width: 100%;
  min-width: 0;
}

.npc-card:not(.npc-card--open) {
  gap: 0;
}

.npc-avatar {
  width: 1.75em;
  height: 1.75em;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--bg-step), rgba(140, 170, 210, 0.18));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85em;
  flex-shrink: 0;
  border: 1px solid var(--border-subtle);
}

.npc-name {
  font-family: var(--font-display);
  font-size: 0.95em;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.2px;
  line-height: 1.25;
  display: inline-flex;
  align-items: center;
  gap: 0.2em;
  flex-shrink: 0;
}

.npc-name-icon {
  font-size: 0.75em;
  color: var(--accent-gold);
}

.npc-identity-inline {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25em;
  flex: 1 1 auto;
  min-width: 0;
  justify-content: flex-start;
}

.npc-identity-tag {
  font-size: 0.62em;
  font-weight: 600;
  line-height: 1.32;
  padding: 0.1em 0.4em;
  border-radius: 5px;
  max-width: 100%;
  word-break: break-word;
  white-space: nowrap;
  background: color-mix(in srgb, var(--accent-gold) 14%, var(--bg-step));
  color: var(--accent-gold);
  border: 1px solid color-mix(in srgb, var(--accent-gold) 35%, var(--border-subtle));
  letter-spacing: 0.1px;
}

.npc-identity-empty {
  font-family: var(--font-mono);
  font-size: 0.6em;
  font-weight: 600;
  padding: 0.12em 0.4em;
  border-radius: 5px;
  color: var(--text-muted, var(--text-secondary));
  background: var(--bg-step);
  border: 1px solid var(--border-subtle);
  white-space: nowrap;
  flex-shrink: 0;
}

.npc-rep-inline {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25em;
  flex: 1 1 auto;
  min-width: 0;
  justify-content: flex-start;
}

.npc-wealth-tag {
  font-family: var(--font-mono);
  font-size: 0.6em;
  font-weight: 600;
  padding: 0.12em 0.4em;
  border-radius: 5px;
  letter-spacing: 0.15px;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

.npc-social-profile {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3em 0.4em;
  width: 100%;

  .npc-rep-inline {
    flex: 1 1 auto;
    min-width: 0;
  }
}

.wealth-destitute {
  background: var(--wealth-destitute-bg);
  color: var(--wealth-destitute-fg);
  border: 1px solid var(--wealth-destitute-bd);
}
.wealth-poor {
  background: var(--wealth-poor-bg);
  color: var(--wealth-poor-fg);
  border: 1px solid var(--wealth-poor-bd);
}
.wealth-tight {
  background: var(--wealth-tight-bg);
  color: var(--wealth-tight-fg);
  border: 1px solid var(--wealth-tight-bd);
}
.wealth-balanced {
  background: var(--wealth-balanced-bg);
  color: var(--wealth-balanced-fg);
  border: 1px solid var(--wealth-balanced-bd);
}
.wealth-comfortable {
  background: var(--wealth-comfortable-bg);
  color: var(--wealth-comfortable-fg);
  border: 1px solid var(--wealth-comfortable-bd);
}
.wealth-welloff {
  background: var(--wealth-welloff-bg);
  color: var(--wealth-welloff-fg);
  border: 1px solid var(--wealth-welloff-bd);
}
.wealth-rich {
  background: var(--wealth-rich-bg);
  color: var(--wealth-rich-fg);
  border: 1px solid var(--wealth-rich-bd);
}
.wealth-tycoon {
  background: var(--wealth-tycoon-bg);
  color: var(--wealth-tycoon-fg);
  border: 1px solid var(--wealth-tycoon-bd);
}

.npc-chip {
  font-size: 0.58em;
  line-height: 1.32;
  padding: 0.1em 0.36em;
  border-radius: 5px;
  max-width: 100%;
  word-break: break-word;
  border: 1px solid var(--border-subtle);
  background: var(--bg-step);
  color: var(--text-secondary);
  white-space: nowrap;

  &--rep {
    font-weight: 600;
    letter-spacing: 0.1px;
  }
}

.rep-hated {
  background: var(--rep-hated-bg);
  color: var(--rep-hated-fg);
  border-color: var(--rep-hated-bd);
}
.rep-infamous {
  background: var(--rep-infamous-bg);
  color: var(--rep-infamous-fg);
  border-color: var(--rep-infamous-bd);
}
.rep-obscure {
  background: var(--rep-obscure-bg);
  color: var(--rep-obscure-fg);
  border-color: var(--rep-obscure-bd);
}
.rep-known {
  background: var(--rep-known-bg);
  color: var(--rep-known-fg);
  border-color: var(--rep-known-bd);
}
.rep-respected {
  background: var(--rep-respected-bg);
  color: var(--rep-respected-fg);
  border-color: var(--rep-respected-bd);
}
.rep-revered {
  background: var(--rep-revered-bg);
  color: var(--rep-revered-fg);
  border-color: var(--rep-revered-bd);
}
.rep-default {
  background: var(--bg-step);
  color: var(--text-secondary);
  border-color: var(--border-subtle);
}

.npc-chain-section {
  background: var(--bg-chain);
  border-radius: var(--radius-sm);
  padding: 0.4em 0.55em;
  border-left: 2px solid var(--border-chain);
  width: 100%;
}

.chain-label {
  font-family: var(--font-mono);
  font-size: 0.68em;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--accent-lavender);
  text-transform: uppercase;
  margin-bottom: 0.2em;
}

.chain-flow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2em;
  font-size: 0.78em;
  color: var(--text-secondary);
  line-height: 1.45;
}

.chain-step {
  background: var(--bg-step);
  color: var(--text-primary);
  padding: 0.1em 0.35em;
  border-radius: 4px;
  font-weight: 500;
  white-space: normal;
  word-break: break-word;
  min-width: 0;
}

.chain-arrow {
  color: var(--accent-gold);
  font-weight: 700;
  flex-shrink: 0;
}

.chain-predict {
  color: var(--accent-rose);
  font-weight: 600;
  font-style: italic;
  word-break: break-word;
  min-width: 0;
}

.chain-debut-tag {
  background: var(--debut-bg);
  color: var(--debut-fg);
  padding: 0.1em 0.35em;
  border-radius: 4px;
  font-weight: 700;
  font-size: 0.85em;
  letter-spacing: 0.2px;
  animation: pulseTag 2s ease-in-out infinite;
  white-space: nowrap;
}

@keyframes pulseTag {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.82;
  }
}

/* —— 分区标题 —— */
.npc-section {
  display: flex;
  flex-direction: column;
  gap: 0.35em;
  width: 100%;
}

.npc-section-head {
  font-family: var(--font-mono);
  font-size: 0.72em;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: var(--accent-lavender);
}

/* 生命档案：紧凑标签行 */
.npc-life-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3em;
  width: 100%;
}

.npc-life-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 0.25em;
  max-width: 100%;
  padding: 0.2em 0.45em;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-mint) 14%, var(--bg-step));
  border: 1px solid color-mix(in srgb, var(--accent-mint) 35%, var(--border-subtle));
  font-size: 0.68em;
  line-height: 1.35;
}

.npc-life-k {
  font-weight: 700;
  color: var(--accent-mint);
  letter-spacing: 0.2px;
  flex-shrink: 0;
}

.npc-life-v {
  color: var(--text-primary);
  word-break: break-word;
  min-width: 0;
}

.npc-companions-card {
  width: 100%;
}

/* 人际与背景：统一容器 */
.npc-relations {
  width: 100%;
  padding: 0.55em 0.6em 0.6em;
  border-radius: var(--radius-md);
  background:
    linear-gradient(
      145deg,
      color-mix(in srgb, var(--accent-sky) 8%, var(--bg-panel, var(--bg-step))) 0%,
      color-mix(in srgb, var(--accent-lavender) 6%, var(--bg-card)) 55%,
      var(--bg-panel, var(--bg-step)) 100%
    );
  border: 1px solid color-mix(in srgb, var(--accent-lavender) 28%, var(--border-subtle));
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 18%, transparent);
}

.npc-relations-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: 0.55em 0.65em;
  width: 100%;
  align-items: start;
}

.npc-relations-block {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35em;

  &--near {
    grid-column: 1;
    grid-row: 1;
  }

  &--bg {
    grid-column: 2;
    grid-row: 1;
  }

  &--social {
    grid-column: 1 / -1;
    grid-row: 2;
    padding-top: 0.45em;
    border-top: 1px dashed color-mix(in srgb, var(--accent-lavender) 35%, var(--border-subtle));
  }
}

/* 仅身边或仅背景时通栏 */
.npc-relations-grid:not(:has(.npc-relations-block--near)) .npc-relations-block--bg,
.npc-relations-grid:not(:has(.npc-relations-block--bg)) .npc-relations-block--near {
  grid-column: 1 / -1;
}

.npc-relations-grid:not(:has(.npc-relations-block--near)):not(:has(.npc-relations-block--bg))
  .npc-relations-block--social {
  padding-top: 0;
  border-top: none;
}

.npc-relations-head {
  display: flex;
  align-items: center;
  gap: 0.3em;
  font-family: var(--font-mono);
  font-size: 0.7em;
  font-weight: 700;
  letter-spacing: 0.35px;
  color: var(--accent-lavender);
  line-height: 1.2;
}

.npc-relations-ico {
  font-size: 0.95em;
  line-height: 1;
}

.npc-relations-count {
  margin-left: auto;
  font-size: 0.9em;
  font-weight: 600;
  color: var(--text-muted, var(--text-secondary));
  background: color-mix(in srgb, var(--accent-lavender) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-lavender) 22%, var(--border-subtle));
  border-radius: 999px;
  padding: 0.05em 0.45em;
  letter-spacing: 0;
}

/* 人物/社交：自适应填满行宽 */
.npc-chip-flow {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35em;
  width: 100%;

  &--fill {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(11.5em, 1fr));
    gap: 0.35em;
  }
}

.npc-person-chip {
  display: flex;
  flex-direction: column;
  gap: 0.12em;
  min-width: 0;
  padding: 0.35em 0.5em;
  border-radius: 8px;
  background: color-mix(in srgb, var(--bg-card) 72%, transparent);
  border: 1px solid var(--border-subtle);
  line-height: 1.35;
  box-shadow: 0 1px 0 color-mix(in srgb, #000 4%, transparent);
}

.npc-person-chip-cat {
  font-size: 0.6em;
  font-weight: 700;
  color: var(--accent-sky);
  letter-spacing: 0.25px;
}

.npc-person-chip-name {
  font-size: 0.76em;
  font-weight: 700;
  color: var(--text-primary);
  word-break: break-word;
}

.npc-person-chip-note {
  font-size: 0.66em;
  color: var(--text-secondary);
  word-break: break-word;
}

/* 背景关联：格内铺满 */
.npc-meta-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35em;
  width: 100%;

  &--fill {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.3em;
  }
}

.npc-meta-chip {
  display: flex;
  flex-direction: column;
  gap: 0.1em;
  min-width: 0;
  padding: 0.32em 0.48em;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-sky) 8%, var(--bg-card));
  border: 1px solid color-mix(in srgb, var(--accent-sky) 22%, var(--border-subtle));
}

.npc-meta-k {
  font-size: 0.58em;
  font-weight: 700;
  color: var(--accent-sky);
  letter-spacing: 0.2px;
}

.npc-meta-v {
  font-size: 0.74em;
  color: var(--text-primary);
  word-break: break-word;
  line-height: 1.35;

  &.muted {
    color: var(--text-muted, var(--text-secondary));
    opacity: 0.75;
  }
}

/* 移动端统一断点：≤640px */
@media (max-width: 640px) {
  .npc-card {
    overflow-x: hidden;
    gap: 0.5em;
  }

  .npc-card-top {
    align-items: flex-start;
    column-gap: 0.4em;
    row-gap: 0.35em;
    padding-right: 1.6em;
  }

  .npc-avatar {
    width: 1.55em;
    height: 1.55em;
    font-size: 0.78em;
  }

  .npc-name {
    flex: 1 1 calc(100% - 3em);
    flex-shrink: 1;
    min-width: 0;
    max-width: 100%;
    font-size: 0.9em;
    word-break: break-word;
    overflow-wrap: anywhere;
  }

  .npc-card-caret {
    position: absolute;
    top: 0.15em;
    right: 0;
    margin-left: 0;
    width: var(--touch-min);
    height: var(--touch-min);
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .npc-identity-inline {
    flex: 1 1 100%;
    order: 3;
    row-gap: 0.3em;
    gap: 0.25em;
  }

  .npc-identity-tag {
    white-space: normal;
    font-size: 0.58em;
  }

  .npc-identity-empty {
    order: 3;
    white-space: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
    font-size: 0.58em;
  }

  .npc-social-profile {
    gap: 0.28em;

    .npc-chip {
      white-space: normal;
      font-size: 0.56em;
    }

    .npc-wealth-tag {
      white-space: normal;
      word-break: break-word;
      overflow-wrap: anywhere;
      font-size: 0.58em;
    }
  }

  .npc-life-row {
    gap: 0.28em;
  }

  .npc-life-chip {
    font-size: 0.64em;
  }

  /* 当前状态：两列 + 通栏 */
  .npc-status-grid {
    &--mapped {
      grid-template-columns: 1fr 1fr;
      grid-template-areas:
        'action wear'
        'world place'
        'env env'
        'doing doing';
    }

    &--mapped:not(.npc-status-grid--has-doing) {
      grid-template-areas:
        'action wear'
        'world place'
        'env env';
    }

    &:not(.npc-status-grid--mapped) {
      grid-template-columns: 1fr 1fr;

      .npc-status-cell--doing {
        grid-column: 1 / -1;
      }
    }
  }

  .npc-status-cell {
    padding: 0.35em 0.42em;
  }

  .npc-status-k {
    font-size: 0.62em;
  }

  .npc-status-v {
    font-size: 0.74em;
    line-height: 1.4;
  }

  /* 人际容器：单列 */
  .npc-relations {
    padding: 0.45em 0.5em 0.5em;
  }

  .npc-relations-grid {
    grid-template-columns: 1fr;
    gap: 0.45em;
  }

  .npc-relations-block--near,
  .npc-relations-block--bg,
  .npc-relations-block--social {
    grid-column: 1;
    grid-row: auto;
  }

  .npc-relations-block--social {
    padding-top: 0.4em;
  }

  .npc-chip-flow--fill {
    grid-template-columns: repeat(auto-fill, minmax(8.5em, 1fr));
  }

  .npc-meta-strip--fill {
    grid-template-columns: repeat(auto-fill, minmax(7.5em, 1fr));
  }

  /* 目标/打算：单列 */
  .npc-duo {
    grid-template-columns: 1fr;
  }

  /* 任务：单列 */
  .npc-quest-logs {
    grid-template-columns: 1fr;
  }

  /* 记忆：窄屏由 container / auto-fit 自行单列；此处只调可读性 */
  .npc-memory-col {
    padding: 0.55em 0.65em;
  }

  .npc-memory-list {
    gap: 0.45em;
  }

  .npc-memory-list li {
    font-size: 0.8em;
    line-height: 1.55;
  }

  .npc-chain-section {
    padding: 0.5em 0.65em;
  }

  .chain-arrow {
    display: none;
  }

  .chain-step,
  .chain-predict {
    flex: 1 1 100%;
    font-size: 0.78em;
    line-height: 1.45;
    padding: 0.35em 0.5em;
  }

  .npc-subcard {
    padding: 0.55em 0.6em 0.6em;
    gap: 0.45em;
  }

  .npc-social-row {
    grid-template-columns: 1fr;
  }

  .npc-plan-line {
    grid-template-columns: 2.4em minmax(0, 1fr);
    font-size: 0.74em;
  }
}

/* 近期打算：紧凑键值行 */
.npc-plan-compact {
  display: flex;
  flex-direction: column;
  gap: 0.25em;
}

.npc-plan-line {
  display: grid;
  grid-template-columns: 2.6em minmax(0, 1fr);
  gap: 0.35em 0.45em;
  align-items: baseline;
  font-size: 0.76em;
  line-height: 1.45;
}

.npc-plan-k {
  font-size: 0.9em;
  font-weight: 700;
  color: var(--accent-sky);
}

.npc-plan-v {
  color: var(--text-primary);
  word-break: break-word;
  min-width: 0;
}

/* 当前状态：语义分区网格（动作/穿着 → 世界/位置/环境 → 正在做） */
.npc-status-grid {
  display: grid;
  gap: 0.4em;
  width: 100%;
  align-items: stretch;
  grid-template-columns: repeat(auto-fit, minmax(7.5em, 1fr));

  &--mapped {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr) minmax(0, 1.35fr);
    grid-template-areas:
      'action wear wear'
      'world place place'
      'env env env'
      'doing doing doing';
  }

  &--mapped:not(.npc-status-grid--has-doing) {
    grid-template-areas:
      'action wear wear'
      'world place place'
      'env env env';
  }
}

.npc-status-cell {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.2em;
  padding: 0.4em 0.5em;
  border-radius: 6px;
  background: var(--bg-step);
  border: 1px solid var(--border-subtle);

  &--doing {
    grid-column: 1 / -1;
    background: color-mix(in srgb, var(--accent-sky) 10%, var(--bg-step));
    border-color: color-mix(in srgb, var(--accent-sky) 28%, var(--border-subtle));
  }
}

.npc-status-grid--mapped {
  .npc-status-cell--action {
    grid-area: action;
  }
  .npc-status-cell--wear {
    grid-area: wear;
  }
  .npc-status-cell--world {
    grid-area: world;
  }
  .npc-status-cell--place {
    grid-area: place;
  }
  .npc-status-cell--env {
    grid-area: env;
  }
  .npc-status-cell--doing {
    grid-area: doing;
    grid-column: auto;
  }
}

.npc-status-k {
  font-size: 0.65em;
  font-weight: 700;
  color: var(--accent-sky);
  letter-spacing: 0.3px;
  margin-bottom: 0.15em;
}

.npc-status-v {
  font-size: 0.78em;
  color: var(--text-primary);
  line-height: 1.4;
  word-break: break-word;
}

/* 双卡：够宽则并排，否则自动折行 */
.npc-duo {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12em, 1fr));
  gap: 0.5em;
  width: 100%;
  align-items: stretch;

  &:has(> :only-child) {
    grid-template-columns: 1fr;
  }
}

.npc-subcard {
  background: var(--bg-panel, var(--bg-step));
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 0.45em 0.55em 0.5em;
  display: flex;
  flex-direction: column;
  gap: 0.35em;
  min-width: 0;
  min-height: 100%;
}

.npc-subcard-head {
  font-family: var(--font-mono);
  font-size: 0.72em;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: var(--accent-lavender);
  padding-bottom: 0.25em;
  border-bottom: 1px dashed var(--border-subtle);
}

.npc-subcard-body {
  display: flex;
  flex-direction: column;
  gap: 0.4em;
  flex: 1;
}

.npc-goal-text {
  margin: 0;
  font-size: 0.8em;
  line-height: 1.5;
  color: var(--text-primary);
  word-break: break-word;
  flex: 1;
}

/* 社交：分类在左，人物在右 */
.npc-social-row {
  display: grid;
  grid-template-columns: 3.2em minmax(0, 1fr);
  gap: 0.35em 0.5em;
  align-items: start;
}

.npc-social-cat {
  font-size: 0.7em;
  font-weight: 700;
  color: var(--accent-sky);
  line-height: 1.45;
  padding-top: 0.1em;
}

.npc-social-people {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25em;
  min-width: 0;
}

.npc-person {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.15em 0.4em;
  padding: 0.2em 0.4em;
  border-radius: 6px;
  background: var(--memory-bg, rgba(0, 0, 0, 0.04));
  border: 1px solid var(--memory-bd, var(--border-subtle));
  max-width: 100%;
}

.npc-person-name {
  font-size: 0.78em;
  font-weight: 700;
  color: var(--text-primary);
}

.npc-person-note {
  font-size: 0.7em;
  color: var(--text-secondary);
  word-break: break-word;
}

/* 背景 / 近期打算：键值行 */
.npc-bg-rows {
  gap: 0.3em;
}

.npc-bg-row {
  display: grid;
  grid-template-columns: 3.5em minmax(0, 1fr);
  gap: 0.35em 0.5em;
  align-items: baseline;
  padding: 0.25em 0.35em;
  border-radius: 6px;
  background: rgba(120, 150, 200, 0.08);
  border: 1px solid rgba(120, 150, 200, 0.2);
}

.npc-bg-key {
  font-size: 0.7em;
  font-weight: 700;
  color: var(--accent-sky);
}

.npc-bg-val {
  font-size: 0.78em;
  color: var(--text-primary);
  word-break: break-word;

  &.muted {
    color: var(--text-muted, var(--text-secondary));
    opacity: 0.75;
  }
}

/* 记忆：按卡片实际宽度自适应；窄屏单列，宽屏再分栏（iframe 内 media 常不准） */
.npc-memory-section {
  gap: 0.45em;
  container-type: inline-size;
  container-name: npc-memory;
}

.npc-memory-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.55em;
  width: 100%;
  align-items: stretch;
}

@container npc-memory (min-width: 36rem) {
  .npc-memory-grid {
    grid-template-columns: repeat(var(--mem-cols, 3), minmax(0, 1fr));
    gap: 0.5em;
  }
}

.npc-memory-col {
  display: flex;
  flex-direction: column;
  gap: 0.35em;
  min-width: 0;
  padding: 0.5em 0.65em;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--memory-bg, var(--bg-step));
  min-height: 100%;

  &--settled {
    background: var(--memory-settled-bg, var(--bg-step));
    border-color: var(--memory-settled-bd, var(--border-subtle));
  }

  &--core {
    background: var(--memory-core-bg, var(--bg-step));
    border-color: var(--memory-core-bd, var(--border-subtle));
  }
}

.npc-memory-col-head {
  display: flex;
  align-items: center;
  gap: 0.3em;
  font-family: var(--font-mono);
  font-size: 0.72em;
  font-weight: 700;
  color: var(--accent-lavender);
  letter-spacing: 0.3px;
  padding-bottom: 0.3em;
  border-bottom: 1px dashed var(--border-subtle);
}

.npc-memory-col--core .npc-memory-col-head {
  color: var(--accent-gold);
}

.npc-memory-count {
  margin-left: auto;
  font-weight: 600;
  opacity: 0.7;
  font-size: 0.95em;
}

.npc-memory-list {
  margin: 0;
  padding: 0 0 0 1.2em;
  display: flex;
  flex-direction: column;
  gap: 0.4em;
  list-style: decimal;
}

.npc-memory-list li {
  font-size: 0.78em;
  line-height: 1.55;
  color: var(--text-secondary);
  word-break: break-word;
  overflow-wrap: anywhere;
  padding-left: 0.15em;
}

.npc-memory-col--core .npc-memory-list li {
  color: var(--text-primary);
}

/* —— 可选任务模块 —— */
.npc-quest-section {
  gap: 0.45em;
}

.npc-section-head {
  display: flex;
  align-items: center;
  gap: 0.4em;
}

.npc-quest-count {
  font-size: 0.85em;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--bg-step);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  padding: 0.05em 0.45em;
  letter-spacing: 0;
}

.npc-quest-logs {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(14em, 1fr));
  gap: 0.45em;
  width: 100%;
  align-items: stretch;
}

.npc-quest-card {
  min-width: 0;
  min-height: 100%;
  height: 100%;
}

.npc-quest-card-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35em 0.5em;
}

.npc-quest-kind {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.65em;
  font-weight: 700;
  letter-spacing: 0.3px;
  padding: 0.12em 0.4em;
  border-radius: 4px;
  border: 1px solid var(--border-subtle);
  line-height: 1.3;
}

.quest-kind--main {
  color: var(--accent-gold);
  background: color-mix(in srgb, var(--accent-gold) 16%, transparent);
  border-color: color-mix(in srgb, var(--accent-gold) 35%, transparent);
}

.quest-kind--side {
  color: var(--accent-sky);
  background: color-mix(in srgb, var(--accent-sky) 16%, transparent);
  border-color: color-mix(in srgb, var(--accent-sky) 35%, transparent);
}

.quest-kind--char {
  color: var(--accent-rose);
  background: color-mix(in srgb, var(--accent-rose) 16%, transparent);
  border-color: color-mix(in srgb, var(--accent-rose) 35%, transparent);
}

.quest-kind--errand {
  color: var(--accent-mint);
  background: color-mix(in srgb, var(--accent-mint) 16%, transparent);
  border-color: color-mix(in srgb, var(--accent-mint) 35%, transparent);
}

.quest-kind--default {
  color: var(--accent-lavender);
  background: var(--bg-step);
}

.npc-quest-title {
  font-size: 0.84em;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.35;
  word-break: break-word;
  min-width: 0;
}

.npc-quest-summary {
  margin: 0;
  font-size: 0.74em;
  line-height: 1.45;
  color: var(--text-muted);
  word-break: break-word;
}

.npc-quest-items,
.npc-quest-children {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.28em;
}

.npc-quest-item {
  display: grid;
  grid-template-columns: 1.1em minmax(0, 1fr);
  column-gap: 0.35em;
  row-gap: 0.2em;
  align-items: start;
  font-size: 0.76em;
  line-height: 1.45;
  color: var(--text-secondary);

  &--done {
    color: var(--text-muted);

    .npc-quest-item-text {
      text-decoration: line-through;
      text-decoration-color: color-mix(in srgb, var(--text-muted) 55%, transparent);
    }
  }

  &--active {
    color: var(--text-primary);
    font-weight: 600;
  }

  &--todo {
    color: var(--text-secondary);
  }
}

.npc-quest-mark {
  font-size: 0.9em;
  line-height: 1.45;
  color: var(--accent-sky);
  text-align: center;
}

.npc-quest-item--done .npc-quest-mark {
  color: var(--accent-mint);
}

.npc-quest-item--active .npc-quest-mark {
  color: var(--accent-gold);
}

.npc-quest-item-text {
  word-break: break-word;
  min-width: 0;
}

.npc-quest-children {
  grid-column: 1 / -1;
  padding-left: 1.35em;
  border-left: 1px dashed var(--border-subtle);
  margin-left: 0.35em;
}

.npc-quest-climax {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35em 0.5em;
  margin-top: 0.15em;
  padding-top: 0.35em;
  border-top: 1px dashed var(--border-subtle);
}

.npc-quest-climax-label {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.65em;
  font-weight: 700;
  letter-spacing: 0.3px;
  color: var(--accent-coral);
}

.npc-quest-climax-text {
  font-size: 0.74em;
  line-height: 1.45;
  color: var(--text-secondary);
  word-break: break-word;
  min-width: 0;
}

.npc-quest-archive {
  display: flex;
  flex-direction: column;
  gap: 0.3em;
  padding: 0.4em 0.5em 0.45em;
  border-radius: var(--radius-sm);
  background: var(--bg-step);
  border: 1px solid var(--border-subtle);
}

.npc-quest-archive-head {
  font-family: var(--font-mono);
  font-size: 0.68em;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: var(--text-muted);
}

.npc-quest-archive-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35em;
}

.npc-quest-archive-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.25em 0.45em;
  font-size: 0.74em;
  line-height: 1.4;
}

.npc-quest-kind--archive {
  opacity: 0.9;
}

.npc-quest-archive-title {
  font-weight: 600;
  color: var(--text-primary);
  word-break: break-word;
}

.npc-quest-archive-date {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.92em;
}

.npc-quest-archive-ending {
  flex: 1 1 100%;
  color: var(--text-secondary);
  word-break: break-word;
}
