
.app-hint {
  padding: 12px 14px;
  color: var(--text-muted, #888);
  font-size: 0.8rem;
  line-height: 1.5;

  code {
    font-size: 0.9em;
  }
}

@media (max-width: 640px) {
  .app-hint {
    padding: var(--space-4, 8px) var(--panel-pad-x, 8px);
    font-size: 0.75rem;
    color: var(--text-muted, #888);
    overflow-wrap: anywhere;
    word-break: break-word;

    code {
      display: inline;
      max-width: 100%;
      white-space: normal;
      overflow-wrap: anywhere;
      word-break: break-all;
    }
  }
}
